export function InvoiceRow({ invoice, onSelect }) {
  const total = invoice.lines.reduce((s, l) => s + l.qty * l.price, 0);
  return (
    <tr onClick={() => onSelect(invoice.id)}>
      <td>{invoice.number}</td>
      <td className="num">{total.toFixed(2)}</td>
    </tr>
  );
}

func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
	defer cancel()
	if err := s.db.PingContext(ctx); err != nil {
		http.Error(w, "db unavailable", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

fn parse_line(line: &str) -> Result<Record, ParseError> {
    let mut parts = line.splitn(3, ',');
    let id = parts.next().ok_or(ParseError::Missing("id"))?.parse::<u64>()?;
    let name = parts.next().ok_or(ParseError::Missing("name"))?.trim().to_owned();
    Ok(Record { id, name })
}

